-- Derive before/after quantities chronologically from zero opening balances.
UPDATE wms_stock_flow f SET before_qty=x.balance-f.change_qty, after_qty=x.balance
FROM (SELECT flow_id, SUM(change_qty) OVER(PARTITION BY inventory_id ORDER BY create_time,flow_id ROWS UNBOUNDED PRECEDING) balance FROM wms_stock_flow) x
WHERE x.flow_id=f.flow_id;
UPDATE wms_inventory i SET qty=x.qty, update_time=x.last_time
FROM (SELECT inventory_id,SUM(change_qty) qty,MAX(create_time) last_time FROM wms_stock_flow GROUP BY inventory_id) x
WHERE x.inventory_id=i.inventory_id;

